def sd(up):
    # best AGGAGG-like match score in last 15 nt
    best=0
    for L in range(6,2,-1):
        for i in range(len(up)-L+1):
            sub=up[i:i+L]
            score=sum(1 for a,b in zip(sub,'AGGAGG'[:L]) if a==b)
            if score>best: best=score
    return best

